'use strict';
function tagColor(value){let hash=0;for(const c of value.toLocaleLowerCase('ru'))hash=(hash*31+c.codePointAt(0))>>>0;return 'tag-color-'+hash%6;}
function tagChips(container,values){container.replaceChildren();container.classList.add('tag-chips');for(const value of values){const chip=document.createElement('span');chip.className='client-tag '+tagColor(value);chip.textContent='#'+value;container.append(chip);}}
function createTagEditor(original){
  original.type='hidden';const wrapper=document.createElement('div');wrapper.className='client-tag-editor';const list=document.createElement('div');list.className='tag-chips';const draft=document.createElement('input');draft.className='client-tag-draft';draft.setAttribute('aria-label','Новый тег');draft.placeholder='Введите тег и нажмите пробел';draft.autocomplete='off';const error=document.createElement('small');error.className='tag-error';error.setAttribute('role','status');wrapper.append(list,draft);original.after(wrapper,error);let tags=[];
  const split=text=>text.split(/[\s|]+/u).map(v=>v.replace(/^#+/u,'')).filter(Boolean);
  function paint(){list.replaceChildren();tags.forEach((value,index)=>{const chip=document.createElement('span');chip.className='client-tag '+tagColor(value);const text=document.createElement('span');text.textContent='#'+value;const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','Удалить тег #'+value);remove.onclick=()=>{tags.splice(index,1);paint();draft.focus();};chip.append(text,remove);list.append(chip);});original.value=tags.join('|');}
  function add(text,throwError=false){const incoming=split(text);if(incoming.some(v=>v.length>80)){error.textContent='Тег не более 80 символов.';if(throwError)throw Error(error.textContent);return false;}const merged=[...tags];for(const tag of incoming)if(!merged.some(v=>v.toLocaleLowerCase('ru')===tag.toLocaleLowerCase('ru')))merged.push(tag);if(merged.length>30){error.textContent='Не более 30 тегов.';if(throwError)throw Error(error.textContent);return false;}tags=merged;draft.value='';error.textContent='';paint();return true;}
  add(original.value);draft.addEventListener('keydown',event=>{if(event.isComposing)return;if([' ','Enter','Tab'].includes(event.key)){if(event.key!=='Tab')event.preventDefault();add(draft.value);}else if(event.key==='Backspace'&&!draft.value){tags.pop();paint();}});draft.addEventListener('input',event=>{if(!event.isComposing&&/[\s|]/u.test(draft.value))add(draft.value);});draft.addEventListener('paste',event=>{const text=event.clipboardData.getData('text');event.preventDefault();add(draft.value+text);});draft.addEventListener('blur',()=>add(draft.value));wrapper.addEventListener('click',event=>{if(event.target===wrapper||event.target===list)draft.focus();});return{read(){add(draft.value,true);return [...tags];},input:draft};
}
